import pytest

import factory


@pytest.mark.parametrize('choice', [False, True])
def test_faker_decider_provider_defaults(choice):
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker('pybool', truth_probability=100 if choice else 0),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['value'] == ('yes' if choice else 'no')


def test_decider_unrolls_defaults_without_branch_overrides():
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker(
                'pybool',
                locale='en_US',
                truth_probability=factory.LazyFunction(lambda: 100),
            ),
            yes_declaration=factory.Faker('pyint', min_value=1, max_value=1),
            no_declaration=0,
        )

    assert ExampleFactory(value__min_value=2, value__max_value=2)['value'] == 2


def test_nested_maybe_decider():
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['value'] == 'yes'
